style.css:
/* 設置所有未點擊的連結為接近白色的亮藍色 */
a {
  color: #add8e6 !important; /* 亮藍色，顏色代碼可以根據需要調整 */
  text-decoration: none; /* 預設去除底線 */
}

/* 設置已點擊的連結為亮紫色 */
a:visited {
  color: #dda0dd !important; /* 亮紫色，顏色代碼可以根據需要調整 */
  text-decoration: none; /* 預設去除底線 */
}

/* 當滑鼠懸停於連結時，顯示底線 */
a:hover {
  text-decoration: underline;
}
